SELECT id, order_id, checkout_id, customer_id, shop_id, pickup_request_id, status, tracking_code, shipping_method, shipping_fee, total_weight_gram, total_volume_m3, package_payload::TEXT AS package_payload, pickup_name, pickup_phone, pickup_address, pickup_latitude, pickup_longitude, receiver_name, receiver_phone, receiver_address, receiver_latitude, receiver_longitude, estimated_delivery_at, picked_up_at, delivered_at, created_at, updated_at FROM shipments WHERE id IN
#{id}
ORDER BY id FOR UPDATE

